(* [comment removed for export] *)
Definition ISHDR_STACK : Z := 16.

Definition ishdr_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns : NS) (b : bool) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (Z.b2z b)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ANSCells m' ns /\ ANSAcc m' ns /\ ACONST m'.

Definition ishdr_stmt : Prop := forall (p : Z) (ns : NS) (b : bool) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSCells m ns -> is_header ns p = Some b ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ISHDR_STACK <= bv_unsigned sp -> aceil <= lo ->     (* [comment removed for export] *)
  mem_inv bsegs m ->
  ANSAcc m ns -> ACONST m ->                                                                  (* [comment removed for export] *)
  evt bsegs (ishdr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns b lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz p) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_RB_IS_HEADER) fc None m (seg_rom bsegs)).

Lemma ishdr_spec : ishdr_stmt.
