Definition rbmax_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns : NS) (r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ANSCells m' ns /\ ANSAcc m' ns /\ ACONST m'.

Definition rbmax_stmt : Prop := forall (n : Z) (ns : NS) (fuel : nat) (r lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSCells m ns -> maximum fuel ns n = Some r ->
  stk bsegs m lo (bv_unsigned sp) -> lo + RBMAX_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  ANSAcc m ns -> ACONST m ->
  evt bsegs (rbmax_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_RB_MAXIMUM) fc None m (seg_rom bsegs)).

Section RbMax.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (ns : NS) (lo : Z) (j8 : list byte).
  Hypothesis LO : lo + RBMAX_STACK <= bv_unsigned sp.
  Hypothesis HC : aceil <= lo.

  Definition rbmax_ctx (m1 : mem) : Prop :=
    rw_cells bsegs m1 (bv_unsigned sp + -16) [CB 8 j8; C8 ra]
    /\ stk bsegs m1 lo (bv_unsigned sp + -16)
    /\ ANSCells m1 ns /\ ANSAcc m1 ns /\ ACONST m1
    /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1.

  (* [comment removed for export] *)
  Lemma rbmax_exit : forall m1 (x1 x5 x6 x7 a1 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word) (r : Z),
    rbmax_ctx m1 ->
    evt bsegs (rbmax_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 0xbe7cc) fc None m1 (seg_rom bsegs)).
