  Lemma rbmax_loop : forall fuel (x r : Z) m1 (x1 x5 x6 x7 a0 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word),
    rbmax_ctx m1 -> maximum fuel ns x = Some r ->
    evt bsegs (rbmax_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0 s1 a0 (wz x) (Z_to_bv 64 2147450880) a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
